"""IELTS Reading L01-L10 PPT Builder — Green Theme"""
import os, sys
sys.path.insert(0, os.path.dirname(__file__))
import ppt_utils as U

OUT = os.path.join(os.path.dirname(__file__), 'reading')
os.makedirs(OUT, exist_ok=True)

def T():
    U.set_theme(U.RGBColor(0x1B,0x5E,0x33), U.RGBColor(0xE0,0x9A,0x10),
                U.RGBColor(0xE8,0xF5,0xE9), U.RGBColor(0x0D,0x2B,0x17),
                '阅读','IELTS Reading')

def part(p,idx,tc,te,concs,conts,exs):
    U.section(p,idx,tc,te)
    for c in concs: U.concept(p,c[0],c[1],c[2],note=c[3] if len(c)>3 else None)
    for c in conts: U.content(p,c[0],c[1],note=c[2] if len(c)>2 else None)
    for e in exs:   U.example(p,e[0],e[1],answer=e[2],tip=e[3] if len(e)>3 else None)

# ─────────────────────────────────────────────────────────────────
#  L01  阅读考试全貌与失分诊断
# ─────────────────────────────────────────────────────────────────
def L01():
    T(); p = U.new_prs()
    U.cover(p,'阅读',1,'阅读考试全貌\n& 失分诊断','Reading Overview & Score Diagnosis')
