          '解题：(1)Germany+percentage→"45%"→答案：45\n(2)Denmark+since→"1990s"→答案：1990s（1词）\n(3)China+began→"2015"→答案：2015\n表格技巧：Country(行)+Policy(列)=交叉定位，精准快速',
