          '分析：\nA."fell steadily"= gradually decreased ✓ "initial interest"= initial enthusiasm ✓\nB."gaining increasing numbers"→ 与原文相反（decreased）✗\nC."remained constant"→ 原文先增后减 ✗\nD."cancelled"→ 原文没提取消 ✗\n答案：A',
