          '分析：\n空1："deteriorated/worsened"=has shown a _____ → decline(B)或rise(G)？\n原文"worsened"→变差→ decline ✓\n\n空2："industrial activity"→ manufacturing(C)/production(H)/output(F)？\n原文"industrial activity"最接近manufacturing(C) ✓\n\n答案：空1=B, 空2=C',
