          '分析：\n句子1：埃及人使用papyrus主要是为了___\n原文："papyrus was used primarily for writing scripts, including religious texts"→B ✓\n\n句子2：与木浆纸不同，papyrus___\n原文："papyrus is derived from the papyrus plant, a type of water plant"→A ✓\n\n答案：1=B, 2=A',
