          '答案：\n1→C："Fleming\'s discovery...was unintentional and occurred in 1928"\n（原文：accidental discovery in 1928）\n2→B："extensive use...resulted in antibiotic resistance"\n（原文：overuse...led to antibiotic resistance）\n3→A："bacterial infections were potentially deadly even when minor"\n（原文：even minor infections could prove fatal）',
