        '原文：\n"Urban heat islands form when cities replace natural land with pavements and buildings that absorb and re-emit heat. Temperatures in city centres can be up to 5°C higher than surrounding rural areas. Trees and vegetation help combat this effect by providing shade and cooling the air through a process called evapotranspiration."\n\n摘要（NO MORE THAN TWO WORDS AND/OR A NUMBER）：\n"Urban heat islands occur when natural surfaces are replaced by _____(1) in cities. City centre temperatures may exceed those in the _____(2) by as much as _____(3). Planting _____(4) is one way to address this problem as they cool the environment through evapotranspiration."',
        '解题：\n(1) pavements and buildings → 但2词限制："hard surfaces"也可，原文说"pavements and buildings"→取"pavements"或用2词"urban surfaces"？→ 最佳：buildings（测词数：pavements and buildings=3词→超限！）→ 填"built surfaces"或考虑：原文改写→ 填"hard surfaces"（2词）✓ 或直接填"buildings"（1词）✓\n\n(2) surrounding rural areas → rural areas（2词）✓\n(3) up to 5°C → 5°C（1数字+1词=2词）✓ 或5 degrees（2词）\n(4) Trees and vegetation → Trees（1词）✓',
