        '选项：\nA. ...significantly less than those from selling physical copies\nB. ...dramatically altered by digital developments\nC. ...instant access to a vast music library worldwide\nD. ...less predictable than before streaming existed\n\n答案：\n1→B（fundamentally changed = dramatically altered）\n2→C（streaming services, instantly accessible worldwide = instant access to a vast library worldwide）\n3→A（income from streaming...considerably lower = earnings...significantly less）',
