          '段落地图：\nP1：空气污染是重大公共健康问题（主题引入）\nP2：主要来源（车+工业）\nP3：一些城市成功减污（转折）\nP4：政府政策作用\nP5：但仍有挑战（结论/转折）\n\n整体：空气污染——来源——成功案例——政策——挑战',
